#!/bin/bash
set -euo pipefail
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B - <<'ZHENJIANG_BUDGET_SINGLE_COMMAND'
"""Create the isolated remote source root once from an embedded sealed payload.

Input: the two embedded base64 fields inserted by prepare_mailbox.py.
Output: a new private root and deploy/deployment.json; no old data is read.
Example: this body is delivered inside the dedicated mailbox cmd.sh.
"""
from __future__ import annotations

import base64
from io import BytesIO
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import stat
import tarfile


ROOT = Path("/data1/home/sunyiq/zhenjiang_four_target_retrain_20260924_001")
PAYLOAD_B64 = ""
RECEIPT_B64 = ""


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"),
                      allow_nan=False).encode("utf-8")


def exclusive_write(path, raw):
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(path, flags, 0o600)
    with os.fdopen(fd, "wb", buffering=0) as handle:
        handle.write(raw)
        os.fsync(handle.fileno())


def main():
    os.umask(0o077)
    payload = base64.b64decode(PAYLOAD_B64, validate=True)
    receipt = json.loads(base64.b64decode(RECEIPT_B64, validate=True))
    if (len(payload) != receipt["payload_bytes"]
            or sha(payload) != receipt["payload_sha256"]
            or len(payload) > 1_000_000):
        raise ValueError("sealed deployment payload identity differs")
    if (ROOT.parent.resolve(strict=True) != ROOT.parent
            or not ROOT.parent.is_dir() or os.path.lexists(ROOT)):
        raise ValueError("isolated deployment root exists or parent differs")

    members = {}
    with tarfile.open(fileobj=BytesIO(payload), mode="r:gz") as archive:
        for item in archive.getmembers():
            name = item.name
            parsed = PurePosixPath(name)
            if (not item.isfile() or parsed.is_absolute() or ".." in parsed.parts
                    or "\\" in name or name in members or item.size > 1_000_000):
                raise ValueError("unsafe, duplicate, or oversized payload member")
            content = archive.extractfile(item)
            if content is None:
                raise ValueError("payload member unreadable")
            raw = content.read(item.size + 1)
            if len(raw) != item.size:
                raise ValueError("payload member size differs")
            members[name] = raw
    if sum(map(len, members.values())) > 1_000_000:
        raise ValueError("expanded payload exceeds bound")
    manifest_raw = members.get("source_manifest.json")
    job_raw = members.get("deploy/job.sh")
    if (manifest_raw is None or job_raw is None
            or sha(manifest_raw) != receipt["manifest_sha256"]
            or sha(job_raw) != receipt["job_sha256"]
            or len(job_raw) != receipt["job_bytes"]
            or sha(members.get("protocol.json", b"")) != receipt["protocol_sha256"]):
        raise ValueError("sealed manifest, protocol or job identity differs")
    manifest = json.loads(manifest_raw)
    protocol = json.loads(members["protocol.json"])
    if (manifest.get("schema") != "zhenjiang-four-target-source-manifest-v1"
            or len(manifest["files"]) != receipt["manifest_files"]
            or set(members) != set(manifest["files"]) | {"source_manifest.json", "deploy/job.sh"}):
        raise ValueError("payload member allowlist differs")
    for name, spec in manifest["files"].items():
        raw = members[name]
        if len(raw) != spec["bytes"] or sha(raw) != spec["sha256"]:
            raise ValueError("payload member identity differs: " + name)
    # All archive checks finish before the exclusive root is created.
    ROOT.mkdir(mode=0o700)
    for name in sorted(members):
        target = ROOT.joinpath(*PurePosixPath(name).parts)
        target.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        exclusive_write(target, members[name])
    (ROOT / "slurm").mkdir(mode=0o700)
    meta = ROOT.stat()
    identity = [meta.st_dev, meta.st_ino]
    stable = {"inode": meta.st_ino, "uid": meta.st_uid,
              "mode": stat.S_IMODE(meta.st_mode)}
    if os.name == "posix" and stable["mode"] != 0o700:
        raise ValueError("new deployment root permissions differ")
    deployment = {"schema": "budget-deployment-v2",
                  "login_root_identity": identity, "root_binding": stable,
                  "deployment_token": protocol["deployment_token"],
                  "protocol_sha256": receipt["protocol_sha256"],
                  "manifest_sha256": receipt["manifest_sha256"],
                  "job_sha256": receipt["job_sha256"],
                  "payload_sha256": receipt["payload_sha256"],
                  "member_count": len(members)}
    metadata_raw = canonical(deployment)
    exclusive_write(ROOT / "deploy" / "deployment.json", metadata_raw)
    print(json.dumps({"status": "deployed_no_training", "root": str(ROOT),
                      "login_root_identity": identity, "root_binding": stable,
                      "deployment_metadata_sha256": sha(metadata_raw),
                      "deployment_token": protocol["deployment_token"],
                      "member_count": len(members),
                      "protocol_sha256": receipt["protocol_sha256"],
                      "manifest_sha256": receipt["manifest_sha256"],
                      "job_sha256": receipt["job_sha256"]}, sort_keys=True))


if __name__ == "__main__":
    main()

ZHENJIANG_BUDGET_SINGLE_COMMAND
